package localchat;
import java.awt.*;import javax.swing.*;
/** Shared semantic colours. Shapes and labels retain meaning without relying on colour alone. */
final class StatusColors {
 static boolean dark(Component c){Color bg=c==null?UIManager.getColor("Panel.background"):c.getBackground();if(bg==null)bg=UIManager.getColor("Panel.background");return bg!=null&&(.2126*bg.getRed()+.7152*bg.getGreen()+.0722*bg.getBlue())<140;}
 static Color color(String state,boolean dark){String s=state==null?"draft":state;int value=s.startsWith("tool:")?(dark?0x69B5FF:0x1766BC):switch(s){case "running","in_progress"->dark?0x69B5FF:0x1766BC;case "partial","pending"->dark?0xF1C35E:0x946000;case "done","completed"->dark?0x72DDA3:0x168044;case "restarted"->dark?0xC299F5:0x8152B5;case "failed"->dark?0xFF999F:0xB42332;case "unconfirmed"->dark?0xFFB782:0xA4470D;default->dark?0xB5BFCE:0x596579;};return new Color(value);}
 static Icon icon(String state,int size){return new Icon(){public int getIconWidth(){return size;}public int getIconHeight(){return size;}public void paintIcon(Component c,Graphics g,int x,int y){Graphics2D a=(Graphics2D)g.create();a.translate(x,y);a.scale(size/14.0,size/14.0);a.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);Color tint=color(state,dark(c));a.setStroke(new BasicStroke(3f));a.setColor(dark(c)?new Color(0x20242B):Color.WHITE);a.drawOval(2,2,10,10);a.setColor(tint);a.setStroke(new BasicStroke(1.4f,BasicStroke.CAP_ROUND,BasicStroke.JOIN_ROUND));a.drawOval(2,2,10,10);String s=state==null?"draft":state;if(s.startsWith("tool:"))s="running";switch(s){case "done","completed"->a.drawPolyline(new int[]{4,6,10},new int[]{7,9,5},3);case "running","in_progress"->a.fillOval(5,5,4,4);case "partial","pending"->a.fillArc(3,3,8,8,90,180);case "restarted"->{a.drawArc(4,4,6,6,20,270);a.drawPolyline(new int[]{8,10,10},new int[]{3,4,6},3);}case "cancelled"->{a.drawLine(5,5,9,9);a.drawLine(5,9,9,5);}case "failed"->{a.drawLine(7,4,7,7);a.fillOval(6,9,2,2);}case "unconfirmed"->{a.drawArc(5,4,4,4,0,180);a.drawLine(9,6,7,8);a.fillOval(6,9,2,2);}case "queued"->{a.drawLine(7,4,7,7);a.drawLine(7,7,9,8);}default->a.drawLine(5,8,9,5);}a.dispose();}};}
 private StatusColors(){}
}
